<?php
require_role(['admin']);
$stats = [
    'appointments' => (int) $pdo->query("SELECT COUNT(*) FROM appointments WHERE status <> 'cancelled'")->fetchColumn(),
    'customers' => (int) $pdo->query("SELECT COUNT(*) FROM users WHERE role = 'customer'")->fetchColumn(),
    'salonists' => (int) $pdo->query("SELECT COUNT(*) FROM users WHERE role = 'salonist'")->fetchColumn(),
    'pending' => (int) $pdo->query("SELECT COUNT(*) FROM appointments WHERE status = 'pending'")->fetchColumn(),
];
$upcomingAppointments = $pdo->query("SELECT a.appointment_date, a.appointment_time, a.status, s.name AS service_name, c.full_name AS customer_name, z.full_name AS salonist_name FROM appointments a JOIN services s ON s.id = a.service_id JOIN users c ON c.id = a.customer_id LEFT JOIN users z ON z.id = a.salonist_id WHERE a.status <> 'cancelled' AND a.appointment_date >= CURDATE() ORDER BY a.appointment_date, a.appointment_time LIMIT 5")->fetchAll();
?>
<section class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p class="text-xs font-semibold uppercase tracking-[.18em] text-rose-500">Studio overview</p><h1 class="mt-2 text-2xl font-semibold tracking-tight sm:text-3xl">Good day, <?= e($_SESSION['full_name']) ?></h1><p class="mt-2 text-sm text-slate-500">A quick overview of Grace Beauty Salon.</p></div><a href="dashboard.php?page=appointments" class="inline-flex items-center justify-center rounded-xl bg-rose-500 px-5 py-3 text-sm font-semibold text-white shadow-sm hover:bg-rose-600">Manage appointments</a></section>
<section class="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4" aria-label="Salon summary">
<?php foreach ([['Appointments', $stats['appointments'], '▣'], ['Customers', $stats['customers'], '♡'], ['Salonists', $stats['salonists'], '✿'], ['Pending bookings', $stats['pending'], '◷']] as [$label, $value, $icon]): ?><article class="flex items-center gap-4 rounded-2xl border border-rose-100 bg-white p-5 shadow-sm"><span class="grid h-12 w-12 place-items-center rounded-2xl bg-rose-50 text-xl text-rose-500"><?= e($icon) ?></span><div><p class="text-sm text-slate-500"><?= e($label) ?></p><p class="mt-1 text-2xl font-semibold"><?= $value ?></p></div></article><?php endforeach; ?>
</section>
<section class="mb-6 grid gap-3 sm:grid-cols-3"><a href="dashboard.php?page=appointments" class="rounded-2xl border border-rose-100 bg-white p-4 shadow-sm transition hover:border-rose-200 hover:bg-rose-50"><p class="text-sm font-semibold text-rose-700">Review appointments</p><p class="mt-1 text-xs text-slate-500">Confirm bookings and assign salonists.</p></a><a href="dashboard.php?page=customers" class="rounded-2xl border border-rose-100 bg-white p-4 shadow-sm transition hover:border-rose-200 hover:bg-rose-50"><p class="text-sm font-semibold text-rose-700">View customers</p><p class="mt-1 text-xs text-slate-500">See registered salon customers.</p></a><a href="dashboard.php?page=salonists" class="rounded-2xl border border-rose-100 bg-white p-4 shadow-sm transition hover:border-rose-200 hover:bg-rose-50"><p class="text-sm font-semibold text-rose-700">Manage salonists</p><p class="mt-1 text-xs text-slate-500">Create and manage staff accounts.</p></a></section>
<section class="rounded-2xl border border-rose-100 bg-white p-5 shadow-sm sm:p-6"><div class="mb-4 flex items-center justify-between gap-3"><div><h2 class="text-lg font-semibold">Upcoming appointments</h2><p class="mt-1 text-sm text-slate-500">The next scheduled salon visits.</p></div><a href="dashboard.php?page=appointments" class="shrink-0 text-sm font-medium text-rose-600">View all</a></div>
<?php if (!$upcomingAppointments): ?><div class="rounded-xl bg-rose-50/70 px-4 py-8 text-center"><p class="font-medium">No upcoming appointments</p><p class="mt-1 text-sm text-slate-500">New bookings will appear here.</p></div><?php else: ?><div class="divide-y divide-rose-50"><?php foreach ($upcomingAppointments as $appointment): ?><article class="flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="font-medium"><?= e($appointment['service_name']) ?> <span class="font-normal text-slate-500">for <?= e($appointment['customer_name']) ?></span></p><p class="mt-1 text-sm text-slate-500"><?= e(date('D, j M Y', strtotime($appointment['appointment_date']))) ?> at <?= e(date('g:i A', strtotime($appointment['appointment_time']))) ?> · <?= e($appointment['salonist_name'] ?: 'Salonist unassigned') ?></p></div><span class="w-fit rounded-full bg-rose-50 px-3 py-1 text-xs font-medium capitalize text-rose-700"><?= e($appointment['status']) ?></span></article><?php endforeach; ?></div><?php endif; ?></section>
